use bus_gateway::Caller;
use sdk::Refusal;
use sdk::generated::{net, secrets, settings};

/// Generated by capgen: one provider per capability namespace, each answering its
/// namespace's calls for the plugin the gateway bound.
pub struct Providers<'p> {
    pub net: &'p dyn net::Provide,
    pub secrets: &'p dyn secrets::Provide,
    pub settings: &'p dyn settings::Provide,
}

/// Generated by capgen: the host one plugin calls the SDK with. It holds the
/// gateway's caller for that plugin and the providers; its fields are private, so a
/// plugin can neither build one for another id nor reach a provider.
pub struct Bound<'g, 'p> {
    caller: Caller<'g>,
    providers: &'p Providers<'p>,
}

impl<'g, 'p> Bound<'g, 'p> {
    /// Binds the providers to the caller the gateway bound. Inputs: the caller and the
    /// providers. Output: the host.
    pub fn new(caller: Caller<'g>, providers: &'p Providers<'p>) -> Self {
        Self { caller, providers }
    }
}

impl sdk::Host for Bound<'_, '_> {
    /// Calls net.request (net.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn net_request(
        &self,
        request: sdk::generated::net::Request,
    ) -> Result<sdk::generated::net::Reply, Refusal> {
        self.caller.call(
            &net::REQUEST,
            request,
            net::check_request_input,
            |request| self.providers.net.request(self.caller.plugin(), request),
            net::check_request_output,
        )
    }

    /// Calls secrets.put_from_owner (secrets.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_put_from_owner(
        &self,
        name: alloc::string::String,
    ) -> Result<sdk::generated::secrets::Secret, Refusal> {
        self.caller.call(
            &secrets::PUT_FROM_OWNER,
            name,
            |name| secrets::check_put_from_owner_input(name),
            |name| {
                self.providers
                    .secrets
                    .put_from_owner(self.caller.plugin(), name)
            },
            secrets::check_put_from_owner_output,
        )
    }

    /// Calls secrets.find (secrets.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_find(
        &self,
        name: alloc::string::String,
    ) -> Result<core::option::Option<sdk::generated::secrets::Secret>, Refusal> {
        self.caller.call(
            &secrets::FIND,
            name,
            |name| secrets::check_find_input(name),
            |name| self.providers.secrets.find(self.caller.plugin(), name),
            secrets::check_find_output,
        )
    }

    /// Calls secrets.forget (secrets.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn secrets_forget(&self, secret: sdk::generated::secrets::Secret) -> Result<(), Refusal> {
        self.caller.call(
            &secrets::FORGET,
            secret,
            secrets::check_forget_input,
            |secret| self.providers.secrets.forget(self.caller.plugin(), secret),
            secrets::check_forget_output,
        )
    }

    /// Calls settings.save_quit (settings.cap) through the gateway.
    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn settings_save_quit(
        &self,
        settings: sdk::generated::settings::QuitSettings,
    ) -> Result<(), Refusal> {
        self.caller.call(
            &settings::SAVE_QUIT,
            settings,
            settings::check_save_quit_input,
            |settings| {
                self.providers
                    .settings
                    .save_quit(self.caller.plugin(), settings)
            },
            settings::check_save_quit_output,
        )
    }
}
